<?php
require_once 'connection/config.php';
require_once '__init.php';
require_once 'inc/StudentCourseAccess.php';
require_once 'inc/RecoveryPlan.php';
require_once 'inc/TimedExam.php';
require_once 'inc/StudentResourceGateway.php';

global $baseUrl;
$conn = db();
$userId = student_course_access_student_id($conn, $_SESSION['username'] ?? '');
$courseId = student_course_access_identifier($courseId ?? '', 40);
$planId = (int) ($planId ?? ($_GET['plan_id'] ?? 0));
$course = $courseId !== null ? student_course_access_course($conn, $courseId) : null;
if (!$course || !$userId || !student_course_access_enrolled($conn, $userId, $course['course_id'])) { http_response_code(403); exit('Course unavailable'); }
$plan = $planId > 0 ? mmh_recovery_plan_load($conn, (int) $userId, (string) $course['course_id'], $planId) : mmh_recovery_plan_resolve($conn, (int) $userId, (string) $course['course_id']);
if (!$plan || !in_array((string) ($plan['status'] ?? ''), ['active', 'completed'], true)) { http_response_code(404); exit('Recovery Plan not found'); }
$plan = mmh_recovery_plan_sync($conn, $plan, (int) $userId, (string) $course['course_id']);
$taskId = (int) ($_GET['task'] ?? 0);
$defaultTask = null; foreach (($plan['items'] ?? []) as $candidateTask) { if (empty($candidateTask['is_completed']) && empty($candidateTask['is_locked'])) { $defaultTask = $candidateTask; break; } }
$taskId = $taskId > 0 ? $taskId : (int) ($defaultTask['id'] ?? 0);
$context = $taskId > 0 ? mmh_recovery_plan_task_context($plan, $taskId) : ['current' => null, 'previous' => null, 'next' => null, 'position' => 0, 'total' => count($plan['items'] ?? []), 'finish' => false];
$current = $context['current'];
$base = rtrim((string) $baseUrl, '/');
$esc = static fn($v): string => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8');
$workspace = mmh_recovery_plan_workspace_url($base, (string) $course['course_id'], (int) $plan['id']);
$taskUrl = static function (array $task) use ($conn, $base, $course, $plan): string {
    if (strtolower((string) ($task['template_type'] ?? '')) === 'timed_exam') {
        $timedExam = mmh_timed_exam_load_for_item($conn, (string) $course['course_id'], (string) $task['item_id'], false);
        if ($timedExam) return $base . '/user/course/' . rawurlencode((string) $course['course_id']) . '/exam/' . (int) $timedExam['id'] . '?recovery_plan=' . (int) $plan['id'] . '&recovery_task=' . (int) $task['id'];
    }
    return mmh_student_resource_url($base, (string) $course['course_id'], (string) $task['item_id'], [
        'recovery_plan_id' => (int) $plan['id'],
        'recovery_task_id' => (int) $task['id'],
    ]);
};
// Reuse the authenticated student shell: it owns the fixed public header,
// theme initialization, shared design tokens, and mobile navigation.
$metatags = $metatags ?? '';
$keywords = $keywords ?? '';
$openGraph = $openGraph ?? '';
$schema = $schema ?? '';
include 'views/user/layouts/user/header.php';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $esc($plan['title']) ?> | <?= $esc($course['course_title']) ?></title><link rel="stylesheet" href="<?= $esc($base . '/resources/css/design-system.css') ?>"><link rel="stylesheet" href="<?= $esc($base . '/resources/css/course-learning.css') ?>"><link rel="stylesheet" href="<?= $esc($base . '/resources/css/student-experience.css') ?>"><link rel="stylesheet" href="<?= $esc($base . '/resources/css/fontawsome5.min.css') ?>"><style>.recovery-workspace{max-width:1180px;margin:0 auto;padding:28px 18px 56px}.recovery-workspace-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;flex-wrap:wrap}.recovery-workspace-eyebrow{color:var(--text-muted);font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.recovery-workspace h1{margin:.25rem 0 .35rem}.recovery-workspace-note{max-width:680px;color:var(--text-secondary);line-height:1.6}.recovery-workspace-progress{margin:20px 0;padding:16px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface)}.recovery-workspace-progressbar{height:10px;overflow:hidden;border-radius:999px;background:var(--surface-hover)}.recovery-workspace-progressbar span{display:block;height:100%;background:var(--primary)}.recovery-workspace-grid{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.5fr);gap:18px}.recovery-workspace-card{padding:18px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface)}.recovery-task-list{display:grid;gap:7px;margin:12px 0 0;padding:0;list-style:none}.recovery-task-list a{display:grid;grid-template-columns:28px minmax(0,1fr);gap:8px;padding:10px;border-radius:var(--radius-sm);color:var(--text-primary);text-decoration:none}.recovery-task-list a:hover,.recovery-task-list a.is-current{background:var(--surface-hover)}.recovery-task-list .state{font-weight:800;color:var(--text-muted)}.recovery-task-list .is-complete .state{color:var(--success)}.recovery-task-list small{display:block;color:var(--text-muted);margin-top:3px}.recovery-current{min-height:220px}.recovery-current h2{margin:.25rem 0 .5rem}.recovery-current-meta{color:var(--text-muted);font-size:.83rem}.recovery-current-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.recovery-coverage-summary{margin-top:18px;padding:12px;border-radius:var(--radius-sm);background:color-mix(in srgb,var(--primary) 8%,var(--surface));color:var(--text-secondary);font-size:.85rem}.recovery-complete{padding:34px;text-align:center}.recovery-complete .fas{font-size:2.5rem;color:var(--success)}@media(max-width:760px){.recovery-workspace{padding:18px 14px 40px}.recovery-workspace-grid{grid-template-columns:1fr}.recovery-current-actions a{width:100%;justify-content:center}}</style></head><body class="course-learning-page"><main class="recovery-workspace"><header class="recovery-workspace-head"><div><div class="recovery-workspace-eyebrow"><?= $esc($course['course_title']) ?> · Focused learning space</div><h1><?= $esc($plan['title']) ?></h1><p class="recovery-workspace-note"><?= $esc($plan['teacher_note'] ?? 'Follow these teacher-selected course tasks in order. Your existing LMS history stays unchanged.') ?></p></div><a class="course-btn course-btn-secondary" href="<?= $esc($base . '/user/course/' . rawurlencode((string) $course['course_id'])) ?>"><span class="fas fa-arrow-left" aria-hidden="true"></span> Return to course</a></header>
<section class="recovery-workspace-progress" aria-label="Recovery Plan progress"><strong><?= (int) ($plan['completed'] ?? 0) ?> / <?= (int) ($plan['total'] ?? 0) ?> tasks complete</strong><div class="recovery-workspace-progressbar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?= (int) (($plan['total'] ?? 0) ? round(($plan['completed'] / $plan['total']) * 100) : 0) ?>"><span style="width:<?= (int) (($plan['total'] ?? 0) ? round(($plan['completed'] / $plan['total']) * 100) : 0) ?>%"></span></div></section>
<?php if (($plan['status'] ?? '') === 'completed'): ?><section class="recovery-workspace-card recovery-complete" role="status"><span class="fas fa-check-circle" aria-hidden="true"></span><h2>Congratulations!</h2><p>You completed your Recovery Plan. Your teacher considers you caught up with the course.</p><p class="recovery-coverage-summary">Recovered through Study Plan. Homework and attendance history remain unchanged.</p><a class="course-btn course-btn-primary" href="<?= $esc($base . '/user/course/' . rawurlencode((string) $course['course_id'])) ?>">Continue Learning</a></section><?php else: ?><div class="recovery-workspace-grid"><section class="recovery-workspace-card"><h2 class="h5">Plan tasks</h2><ol class="recovery-task-list"><?php foreach (($plan['items'] ?? []) as $task): ?><li><a class="<?= $current && (int) $current['id'] === (int) $task['id'] ? 'is-current ' : '' ?><?= !empty($task['is_completed']) ? 'is-complete' : '' ?>" href="<?= $esc($workspace . '?task=' . (int) $task['id']) ?>"><span class="state"><?php if (!empty($task['is_completed'])): ?><span class="fas fa-check" aria-hidden="true"></span><?php elseif (!empty($task['is_locked'])): ?><span class="fas fa-lock" aria-hidden="true"></span><?php else: ?><span class="far fa-circle" aria-hidden="true"></span><?php endif; ?></span><span><strong><?= $esc($task['item_title']) ?></strong><small><?= !empty($task['is_completed']) ? 'Completed' : (!empty($task['is_locked']) ? 'Locked until the previous task' : ($task['is_required'] ? 'Required' : 'Optional')) ?></small></span></a></li><?php endforeach; ?></ol></section><section class="recovery-workspace-card recovery-current"><div class="recovery-workspace-eyebrow">Current task<?= $context['position'] ? ' · ' . (int) $context['position'] . ' of ' . (int) $context['total'] : '' ?></div><?php if (!$current): ?><h2>Choose your first task</h2><p class="recovery-workspace-note">Start with the first unlocked item selected by your teacher.</p><div class="recovery-current-actions"><a class="course-btn course-btn-primary" href="<?= $esc($workspace . '?task=' . (int) (($plan['items'][0]['id'] ?? 0))) ?>">Start Recovery Plan</a></div><?php else: ?><h2><?= $esc($current['item_title']) ?></h2><p class="recovery-current-meta"><?= $esc($current['section_title'] ?: 'Course item') ?> · <?= $esc(mmh_recovery_plan_item_label($current)) ?></p><?php if (($current['teacher_note'] ?? '') !== ''): ?><p class="recovery-workspace-note"><?= $esc($current['teacher_note']) ?></p><?php endif; ?><div class="recovery-current-actions"><a class="course-btn course-btn-primary" href="<?= $esc($taskUrl($current)) ?>"><span class="fas fa-play" aria-hidden="true"></span> <?= !empty($current['is_completed']) ? 'Review item' : 'Continue' ?></a><?php if ($context['previous']): ?><a class="course-btn course-btn-secondary" href="<?= $esc($taskUrl($context['previous'])) ?>">Previous Task</a><?php endif; ?><?php if ($context['next']): ?><a class="course-btn course-btn-secondary" href="<?= $esc($taskUrl($context['next'])) ?>">Next Task</a><?php else: ?><a class="course-btn course-btn-secondary" href="<?= $esc($workspace) ?>">Finish Plan</a><?php endif; ?></div><?php endif; ?><div class="recovery-coverage-summary"><strong>Coverage</strong><br><?= (int) ($plan['coverage_total'] ?? 0) ?> explicitly mapped topic/item/section targets will be labeled “Covered through Recovery Plan” after their task is complete.</div></section></div><?php endif; ?></main></body></html>
